JavaServerConnection::JavaServerConnection():session(nullptr){}
JavaServerConnection::~JavaServerConnection(){}
bool JavaServerConnection::connect(const std::string&,const std::string&,bool){session=reinterpret_cast<TcpeJavaSession*>(1);return true;}
void JavaServerConnection::disconnect(){session=nullptr;}
bool JavaServerConnection::send(const std::string& json){sent=json;return true;}
bool JavaServerConnection::chat(const std::string& text){sent="chat:"+text;return true;}
bool JavaServerConnection::number(const std::string& path,double& out)const{auto i=numbers.find(path);if(i==numbers.end())return false;out=i->second;return true;}
bool JavaServerConnection::boolean(const std::string& path,bool& out)const{if(path=="cleared"){out=clearDialog;return true;}auto i=booleans.find(path);if(i==booleans.end())return false;out=i->second;return true;}
bool JavaServerConnection::text(const std::string& path,std::string& out)const{auto i=strings.find(path);if(i==strings.end())return false;out=i->second;return true;}
bool JavaServerConnection::arraySize(const std::string& path,size_t& out)const{auto i=arrays.find(path);if(i==arrays.end())return false;out=i->second;return true;}
int JavaServerConnection::pump(const std::function<void(const TcpeJavaEvent&)>& consume,int){if(closeAfterPoll){closeAfterPoll=false;session=nullptr;}if(!pending)return 0;pending=false;TcpeJavaEvent e{};e.kind=eventKind;consume(e);return 1;}
